const inp = $input.first().json;

const msgData = { telefono: inp.telefono, texto: inp.texto || '', nombreContacto: inp.nombreContacto || '' };
const kbContexto = inp.kbContexto || '';
const configData = { records: [{ fields: inp.configEmpresa || {} }] };
const waConfigData = { records: [{ fields: inp.waConfig || {} }] };
const leadData = { records: inp.leadId ? [{ id: inp.leadId, fields: inp.leadFields || {} }] : [] };
const productosData = { records: (inp.productosRaw || []) };

const config = configData.records?.[0]?.fields || {};
const waConfig = waConfigData.records?.[0]?.fields || {};
const emailVendedor = config.WA_Email_Vendedor || 'risosadmi@gmail.com';
const followup24 = waConfig.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || '';

const leadExistente = leadData.records?.[0];
const leadId = leadExistente?.id || null;
const leadFields = leadExistente?.fields || {};

let datosRecolectados = {
  producto: leadFields.Articulo || null,
  medidas: leadFields['Medidas y Peso'] || null,
  fecha: null,
  tipo_cajon: null,
  proteccion_extra: null,
  correo_contacto: null,
  nombre_cliente: leadFields.Nombre_Contacto || null,
  tipo_flujo: null
};

let notasOriginal = {};
try {
  const notas = leadFields.Notas || '';
  if (notas && notas.trim().startsWith('{')) {
    const stored = JSON.parse(notas);
    notasOriginal = stored;
    if (stored.tipo_cajon)       datosRecolectados.tipo_cajon = stored.tipo_cajon;
    if (stored.correo_contacto)  datosRecolectados.correo_contacto = stored.correo_contacto;
    if (stored.nombre_cliente && !datosRecolectados.nombre_cliente) datosRecolectados.nombre_cliente = stored.nombre_cliente;
    if (stored.proteccion_extra !== null && stored.proteccion_extra !== undefined) datosRecolectados.proteccion_extra = stored.proteccion_extra;
    if (stored.fecha)            datosRecolectados.fecha = stored.fecha;
    if (stored.tipo_flujo)       datosRecolectados.tipo_flujo = stored.tipo_flujo;
  }
} catch(e) {}

const r3 = leadFields['¿Protección adicional?'] || '';
if (r3 === 'true')  datosRecolectados.proteccion_extra = true;
else if (r3 === 'false') datosRecolectados.proteccion_extra = false;

const estado = leadFields.Estado || 'Nuevo';
const escaladaEnviada = notasOriginal.escalada_enviada === true;
const idiomaGuardado = notasOriginal.idioma || null;
const historialRaw = leadFields.Historial_Mensajes || '';
const historial = historialRaw ? historialRaw.split('\n').slice(-20).join('\n') : '';
const esNuevo = !leadId;

const catalogoProductos = (productosData.records || []).map(r => {
  const f = r.fields;
  return Object.entries(f).find(([k]) => k.includes('Nombre de Servicio'))?.[1] || '';
}).filter(l => l.length > 2).join(', ');

const horaMiami = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = horaMiami >= 6 && horaMiami < 12 ? 'buenos días'
  : horaMiami >= 12 && horaMiami < 19 ? 'buenas tardes' : 'buenas noches';
const saludo = saludoHora.charAt(0).toUpperCase() + saludoHora.slice(1);
const saludoEN = horaMiami >= 6 && horaMiami < 12 ? 'Good morning' : horaMiami >= 12 && horaMiami < 19 ? 'Good afternoon' : 'Good evening';

const texto = (msgData.texto || '').trim();

// Detectar idioma del MENSAJE ACTUAL
const textoActual = texto.toLowerCase();
const palabrasEN_actual = (textoActual.match(/\b(i|the|you|need|have|want|please|thanks|yes|no|for|and|my|is|are|can|would|like|some|to|of|in|with|it|this|that|hi|hello|good|morning|afternoon|evening|closed|open|crate|inches|inch|need|done|by|next|about|looking|want|send|ship|pack|protection|foam|email|quote|price)\b/g) || []).length;
const palabrasES_actual = (textoActual.match(/\b(quiero|necesito|tengo|hola|gracias|por favor|sí|no|para|con|una|un|que|me|mi|el|la|los|las|de|en|es|son|buenas|buenos|necesito|embalar|cajón|cerrado|abierto|medidas|correo|cotización|precio|protección|espuma|burbuja)\b/g) || []).length;
const isGreeting = /^(hola[sa]?\b|hi\b|buenas\b|buenos\b|hey\b|good\s|morning|afternoon|evening|hello\b)/i.test(texto);
// Lock idioma once detected — only recalculate on greeting or first message
let idiomaConversacion;
if (idiomaGuardado && !isGreeting) {
  idiomaConversacion = idiomaGuardado; // keep locked idioma
} else {
  // Solo bloquear si 0 palabras de ningún idioma (números, emojis puros)
  const totalDetected = palabrasEN_actual + palabrasES_actual;
  if (totalDetected === 0) {
    idiomaConversacion = idiomaGuardado || 'español'; // sin señal suficiente — no cambiar
  } else {
    idiomaConversacion = palabrasEN_actual >= palabrasES_actual ? 'inglés' : 'español';
  }
}

// Saludo en cliente existente = nueva sesión, resetear tipo_flujo y cotizacion
if (isGreeting && !esNuevo) {
  datosRecolectados.tipo_flujo = null;
  // Si saludan de nuevo días después, resetear cotizacion para que puedan pedir una nueva
  // (evita que queden atrapados en POST_COTIZACION para siempre)
}
// cotizacion_enviada también se resetea si el cliente saluda (para permitir nueva cotización)
const cotizacionEnviada = (isGreeting && !esNuevo) ? false : (notasOriginal.cotizacion_enviada === true);
const escaladaPendiente = (isGreeting && !esNuevo) ? false : (notasOriginal.escalada_pendiente === true);

// Extracción de nombre en JavaScript — no depender del AI para esto
if (!datosRecolectados.nombre_cliente) {
  const t = texto.trim();
  // Blocklists
  const IM_BLOCKLIST = new Set(['Good','Done','Ready','Asking','Thinking','Looking','Calling','Available','Interested','Waiting','Here','Fine','Ok','Sure','Back','From','With','Just','Not','Also','Going','Coming','Sending','Trying','Working','Using','A','An','The','In','At','On']);
  const SOY_BLOCKLIST = new Set(['vendedor','ingeniero','contador','abogado','doctor','profesora','profesor','arquitecto','diseñador','diseñadora','gerente','director','directora','trabajador','empleado','cliente','proveedor','representante','agente','asesor','asesora','jefe','dueño','dueña','encargado','encargada','asistente','secretaria','secretario','operador','técnico','mecánico','electricista','conductor','chofer','contratista','freelance','consultor','consultora']);

  // Priority 1: "my name is X", "me llamo X", "soy X" — /i para el trigger, filtra mayúsculas en captura
  const matchExplicito = t.match(/(?:my name is\s+|me llamo\s+|soy\s+(?:yo\s+)?)([A-ZÁÉÍÓÚÜÑa-záéíóúüñ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ]+(?:\s+[A-ZÁÉÍÓÚÜÑa-záéíóúüñ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ]+)?)/i);
  if (matchExplicito) {
    const words = matchExplicito[1].trim().split(' ');
    const nameWords = [];
    for (const w of words) {
      if (/^[A-ZÁÉÍÓÚÜÑ]/.test(w)) nameWords.push(w);
      else break;
    }
    const nombreLimpio = nameWords.join(' ');
    if (nombreLimpio && !SOY_BLOCKLIST.has(nombreLimpio.split(' ')[0].toLowerCase())) {
      datosRecolectados.nombre_cliente = nombreLimpio;
    }
  }
  if (!datosRecolectados.nombre_cliente) {
    // Priority 2: "I'm [Nombre]" — requiere mayúscula real, no en blocklist
    const matchIm = t.match(/\bI'?m\s+([A-ZÁÉÍÓÚÜÑ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ]+)\b/);
    if (matchIm && !IM_BLOCKLIST.has(matchIm[1])) {
      datosRecolectados.nombre_cliente = matchIm[1].trim();
    } else {
      // Priority 3: "call me X" / "name's X"
      const matchCallMe = t.match(/(?:call me|you can call me|just call me|name's|my name's)\s+([A-ZÁÉÍÓÚÜÑa-záéíóúüñ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ]+(?:\s+[A-ZÁÉÍÓÚÜÑa-záéíóúüñ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ]+)?)/i);
      if (matchCallMe) {
        datosRecolectados.nombre_cliente = matchCallMe[1].trim();
      } else if (/^[A-ZÁÉÍÓÚÜÑa-záéíóúüñ]+([ \-][A-ZÁÉÍÓÚÜÑa-záéíóúüñ]+){0,2}$/.test(t) && t.length >= 3 && t.length <= 40 && !t.includes('?')) {
        datosRecolectados.nombre_cliente = t.replace(/\b\w/g, c => c.toUpperCase());
      }
    }
  }
}

const cleanCheck = v => {
  if (typeof v === 'boolean') return v;
  if (!v || ['desconocido','null','undefined'].includes(String(v).toLowerCase().trim())) return null;
  return v;
};

const calcProximoPaso = d => {
  if (cotizacionEnviada)                     return 'POST_COTIZACION';
  if (escaladaEnviada)                       return 'CONSULTA_REGISTRADA';
  if (escaladaPendiente)                     return 'FLUJO_CONSULTA';  // mantener en flujo consulta hasta tener correo
  if (esNuevo)                               return 'PRIMER_CONTACTO';
  if (!cleanCheck(d.nombre_cliente))         return 'PEDIR_NOMBRE';
  if (!d.tipo_flujo)                         return 'IDENTIFICAR_NECESIDAD';
  if (d.tipo_flujo === 'consulta')           return 'FLUJO_CONSULTA';
  if (!cleanCheck(d.producto))               return 'PEDIR_PRODUCTO';
  if (!cleanCheck(d.medidas))                return 'PEDIR_MEDIDAS';
  if (!cleanCheck(d.correo_contacto))        return 'PEDIR_CORREO';
  if (!cleanCheck(d.tipo_cajon))             return 'PEDIR_TIPO_CAJON';
  if (d.proteccion_extra === null || d.proteccion_extra === undefined) return 'PEDIR_PROTECCION';
  if (!cleanCheck(d.fecha))                  return 'PEDIR_FECHA';
  return 'LISTO_PARA_COTIZAR';
};

const proximoPaso = calcProximoPaso(datosRecolectados);
const todosRecolectados = proximoPaso === 'LISTO_PARA_COTIZAR';

const dimensiones = datosRecolectados.medidas ? (() => {
  const nums = (datosRecolectados.medidas || '').match(/(\d+(?:\.\d+)?)/g);
  return nums && nums.length >= 3
    ? { largo: parseFloat(nums[0]), ancho: parseFloat(nums[1]), alto: parseFloat(nums[2]) }
    : null;
})() : null;

// Instrucción simple por paso — la IA maneja todas las variantes
const pasoInstrucciones = {
  PRIMER_CONTACTO:       (() => {
    const nombreYaConocido = datosRecolectados.nombre_cliente;
    if (idiomaConversacion === 'inglés') {
      return nombreYaConocido
        ? `Start with: "${saludoEN}, ${nombreYaConocido}! I'm Marco from Crating Express." Then in the SAME message confirm what they already shared (product, measurements, date, etc.) and ask ONLY for what is still missing. Do NOT ask for their name — you already have it.`
        : `Start with: "${saludoEN}, I'm Marco from Crating Express. Who am I speaking with?" Extract any other data already mentioned (product, measurements, date) and confirm it in the same message.`;
    } else {
      return nombreYaConocido
        ? `Comienza con: "${saludo}, ${nombreYaConocido}! Soy Marco de Crating Express." Luego en EL MISMO mensaje confirma lo que ya mencionaron (producto, medidas, fecha, etc.) y pregunta SOLO lo que falta. NO preguntes el nombre — ya lo tienes.`
        : `Comienza con: "${saludo}, soy Marco de Crating Express. ¿Con quién tengo el gusto?" Extrae cualquier otro dato ya mencionado (producto, medidas, fecha) y confírmalo en el mismo mensaje.`;
    }
  })(),

  CONSULTA_REGISTRADA:   idiomaConversacion === 'inglés'
    ? `Your inquiry has already been logged. Say: "Your question is with our team — someone will reach out shortly. Is there anything else I can help you with?" Do NOT ask for more data or collect additional info.`
    : `La consulta ya fue registrada. Di: "Ya pasamos tu consulta al equipo, te contactarán en breve. ¿Hay algo más en lo que pueda ayudarte?". NO hagas más preguntas de datos ni recopiles información adicional.`,
  PEDIR_NOMBRE:          idiomaConversacion === 'inglés'
    ? `The client just replied with their name. Extract it in the 'nombre' field. In your response: greet them by name ("Hey [name]!") and immediately continue with what they were asking about — do NOT ask for their name again, do NOT ask "how can I help?" if they already stated their need.`
    : `El cliente acaba de responder con su nombre. Extráelo en el campo 'nombre'. En tu respuesta: salúdalo por su nombre ('Hola [nombre], un gusto.') y continúa inmediatamente con lo que el cliente planteó antes — NO vuelvas a preguntar el nombre, NO preguntes '¿en qué puedo ayudarte?' si ya dijeron lo que necesitan. Si no hay contexto previo, pregunta en qué puedes ayudar.`,
  IDENTIFICAR_NECESIDAD: idiomaConversacion === 'inglés'
    ? `Check the history and current message. If the client already asked a question or mentioned what they need, respond directly and set the intent (cotizacion or consulta). Do NOT ask "how can I help you?" if the client already said what they want.`
    : `Revisa el historial y el mensaje actual. Si el cliente ya hizo una pregunta o mencionó lo que necesita, RESPÓNDELA directamente y marca el intento (cotizacion o consulta). NO preguntes "¿en qué puedo ayudarte?" si el cliente ya dijo lo que quiere.`,
  FLUJO_CONSULTA:        idiomaConversacion === 'inglés'
    ? `Answer the client's question using available catalog, policies, and company info.
If the question is OUTSIDE your knowledge or requires human confirmation (specific dates, pricing, discounts, contracts, commercial accounts, volume agreements, negotiations, claims, warranties, special conditions): in the same message say you're passing the inquiry AND ask for email if you don't have it (e.g. "Got it. What's your email so our team can reach you?"). If you already have their email, say: "Perfect, I'm passing your inquiry to our team — someone will be in touch shortly." and mark escalada=true. NEVER invent who handles what or assume you can resolve something not in your catalog.
If they ask for a quote or want to pack something, mark intent=cotizacion.
DAMAGE CLAIMS: If client mentions damage or claim on existing order: first message show empathy + policy; second message direct to cratingexpress01@gmail.com with photos, mark escalada=true. Max 2 messages.`
    : `Responde la pregunta del cliente con la información disponible del catálogo, políticas y empresa.
Si la pregunta está FUERA de tu conocimiento o requiere confirmación humana (disponibilidad de fechas específicas, precios, descuentos, contratos, acuerdos comerciales, términos de negociación, quién atiende qué, reclamos, garantías, especificaciones no documentadas, condiciones especiales): en el mismo mensaje di que vas a pasar la consulta Y pide el correo si no lo tienes (ej: "Entendido. ¿Cuál es tu correo para que el equipo te contacte?"). Si ya tienes el correo, di: "Listo, voy a pasar tu consulta a nuestro equipo — un agente te contactará en breve." y marca escalada=true. NUNCA inventes quién atiende ni asumas que puedes resolver algo que no está en tu catálogo.
Si después pide cotización o quiere embalar algo, marca intento=cotizacion.
QUEJAS Y DAÑOS — REGLA ABSOLUTA: Si el cliente menciona daño, cajón roto, mercancía afectada, garantía o reclamo sobre un pedido existente: en el PRIMER mensaje expresa empatía y da la política ('Lamentamos lo sucedido. Evaluamos todos los casos y respondemos formalmente.'); en el SEGUNDO mensaje dirige al cliente a cratingexpress01@gmail.com con fotos del daño y marca escalada=true. NO sigas más allá de 2 mensajes.`,
    PEDIR_PRODUCTO:        idiomaConversacion === 'inglés'
    ? `If the client mentions the item in this message, extract it in "producto". If they mention a quantity (e.g. "15 bottles", "3 paintings"), extract it in "cantidad". If no item mentioned, ask what they need to crate and how many units.`
    : `Si el cliente menciona el artículo en este mensaje, extráelo en "producto". Si menciona una cantidad (ej: "15 botellas", "3 cuadros"), extráela en "cantidad". Si no hay artículo, pregunta qué necesita embalar y cuántas unidades.`,
  PEDIR_MEDIDAS:         idiomaConversacion === 'inglés'
    ? `If the message contains measurements (numbers), extract them in "medidas" and confirm briefly.
If the client says they don't have measurements yet, or just wants general info/pricing: do NOT insist — in the same message say you'll pass the inquiry to an agent AND ask for email if you don't have it yet (e.g. "No problem. What's your email so our team can send you pricing options?"). If you already have their email, say: "Got it, I'll pass this to our team — someone will be in touch shortly." and mark escalada=true.
If no measurements and no indication they don't have them, ask: "What are the measurements in inches? (Length × Width × Height)" — NEVER mention centimeters.`
    : `Si el mensaje contiene medidas (números), extráelas en "medidas" y confirma con una frase corta.
Si el cliente dice que NO tiene las medidas aún, o solo quiere información/precio general: NO insistas — en el mismo mensaje di que vas a pasar la consulta a un agente Y pide su correo si aún no lo tienes (ej: "Entendido. ¿Cuál es tu correo para que el equipo te contacte con opciones de precio?"). Si ya tienes el correo, di directamente: "Listo, voy a pasar tu consulta a nuestro equipo — un agente te contactará en breve." y marca escalada=true.
Si no hay medidas ni indicación de que no las tiene, pregunta exactamente: "¿Cuáles son las medidas en pulgadas? (Largo × Ancho × Alto)" — NUNCA menciones centímetros.`,
  PEDIR_TIPO_CAJON:      idiomaConversacion === 'inglés'
    ? `If the client asks for a recommendation or doesn't know, recommend the closed crate (safest, ISPM-15 included). If they indicate a preference, extract it in "tipo_cajon".`
    : `Si el cliente pide recomendación o no sabe, recomienda el cajón cerrado (más seguro, ISPM-15 incluido). Si indica preferencia, extráela en "tipo_cajon".`,
  PEDIR_PROTECCION:      idiomaConversacion === 'inglés'
    ? `Ask if they need interior protection (foam, bubble wrap, corner guards) — extra cost. If the client says any affirmative ('yes', 'add it', 'the safest', 'sure', 'please', etc.) → extract proteccion_extra=true and move to date WITHOUT asking for confirmation. If the client says any negative ('no', 'no thanks', 'just the crate', 'nothing extra', 'that's fine', 'not needed', etc.) → extract proteccion_extra=false and move to date. If the client asks a different question → answer it briefly (1 sentence) and then ask about protection again.`
    : `Pregunta si necesita protección interior (foam, burbuja, esquineras) — tiene costo adicional. Si el cliente dice cualquier afirmativo ('sí', 'agrégala', 'la más segura', 'sí por favor', etc.) → extrae proteccion_extra=true y avanza a la fecha SIN pedir confirmación. Si el cliente dice cualquier negativo ('no', 'que no', 'no gracias', 'sin protección', 'solo el cajón', 'nada extra', 'así está bien', 'no necesito') → extrae proteccion_extra=false y avanza a la fecha. Si el cliente hace una pregunta diferente → respóndela brevemente (1 oración) y luego pregunta sobre la protección de nuevo.`,
  PEDIR_FECHA:           idiomaConversacion === 'inglés'
    ? `Ask when they need the crating done. If they already mentioned it, extract it in "fecha". NEVER ask about pickup, delivery, address, or shipping logistics.`
    : `Pregunta para cuándo necesita el embalaje. Si ya lo mencionó, extráelo en "fecha". NUNCA preguntes sobre recogida, entrega, dirección ni logística.`,
  LISTO_PARA_COTIZAR:    idiomaConversacion === 'inglés'
    ? `Say EXACTLY this and nothing else: 'Give me a moment to calculate the price... 🔄'. Do NOT ask questions. Do NOT mention quotes, vendors, or procedures. Just that message.`
    : `Di EXACTAMENTE este texto y nada más: 'Dame un momento para calcular el precio... 🔄'. NO hagas preguntas. NO menciones cotización, vendedor ni procedimientos. Solo ese mensaje.`,
  PEDIR_CORREO:          idiomaConversacion === 'inglés'
    ? `Ask for the client's email. Say: "What's your email so we can follow up?" If already in message, extract in 'correo', confirm with "Got it" and in THE SAME message ask the next pending question (type of crate or protection). Do NOT mention sending a quote yet.`
    : `Pide el correo del cliente. Di: "¿Cuál es tu correo para darte seguimiento?" Si ya está en el mensaje, extráelo en 'correo', confirma con "Anotado" y en EL MISMO mensaje pregunta el siguiente dato pendiente (tipo de cajón o protección). NO menciones cotización todavía.`,
  POST_COTIZACION:       idiomaConversacion === 'inglés'
    ? `Check the CURRENT message from the client:
- If the client ACCEPTS (says yes, ok, sure, please, send it, go ahead, etc.) → confirm briefly: "Perfect, the formal quote is on its way to [email]. Reach out anytime!" and do NOT ask more questions.
- If the client says GOODBYE (says thanks, ok thanks, bye, have a good day, take care, etc.) → respond only: "Take care! 👋" and nothing else.
- If the client has NOT responded yet or asks about the price → remind them of the estimate and ask if they'd like the formal quote sent to their email.
- NEVER repeat the same response twice. Do NOT invent a new price.`
    : `Revisa el MENSAJE ACTUAL del cliente:
- Si el cliente ACEPTA (dice sí, si, sisi, ok, claro, yes, dale, please, por favor, mándame, send it, etc.) → confirma brevemente: "Perfecto, te llega la cotización formal a [correo]. ¡Cualquier duda estamos aquí!" y NO hagas más preguntas.
- Si el cliente se DESPIDE (dice gracias, ok gracias, buen día, bye, hasta luego, chao, good day, thank you, etc.) → responde solo: "¡Hasta luego! 👋" y no agregues nada más.
- Si el cliente aún NO ha respondido o pregunta por el precio → recuérdale el estimado y pregunta si desea la cotización formal a su correo.
- NUNCA repitas la misma respuesta dos veces. No inventes un precio nuevo.`
};

const instruccionPaso = pasoInstrucciones[proximoPaso] || 'Responde al cliente de forma útil.';

const sistemaIA = idiomaConversacion === 'inglés'
? `You are Marco, sales assistant at Crating Express in Miami. ALWAYS respond in English. Direct, concise, casual — Miami moves fast. Max 2 sentences per message. NEVER use: "Great!", "Excellent choice!", "My pleasure!", "Happy to help!", "Certainly!" — they sound like a call center. Vary confirmations — never use the same one twice in a row: "Done.", "Got it.", "Sure.", "Perfect.", "Noted." NEVER repeat info the client already gave.
NEVER ask about pickup, delivery, address, or shipping method — that is not part of the flow.
If the client asks an off-flow question while collecting data, answer it in 1 sentence and then continue with the pending question in the same message.
IMMEDIATE ESCALATION RULE: If the client asks to speak with someone else, a supervisor, sales, a human, or says they are not ready to give data ("it's for the future", "I just want terms", "connect me with someone", etc.) → STOP all questions, ask for their email if you don't have it ("What email can we reach you at?") and mark escalada=true. NO more data questions.
NEVER ASSUME info you don't have: don't invent who handles contracts, don't say "you can contact me directly", don't confirm dates, prices, discounts, or conditions not in the catalog. If you don't know the exact answer → escalate. Inventing info is worse than not knowing.
NEVER end a message without asking the client a question — except in LISTO_PARA_COTIZAR or POST_COTIZACION. If you confirmed a data point, immediately ask the next pending one.
CATALOG: ${catalogoProductos || 'closed crates, open crates/cages, custom pallets, cradles, container platforms, trade show packaging'}
ISPM-15 included in all crates at no extra cost. Measurements ALWAYS in inches — NEVER mention centimeters or meters.

Respond ONLY with valid JSON (no markdown, no text before or after):
{"intento":"cotizacion|consulta|saludo|otro","nombre":null,"producto":null,"cantidad":null,"medidas":null,"tipo_cajon":null,"proteccion_extra":null,"fecha":null,"correo":null,"escalada":null,"respuesta":"message for the client"}

